package com.taylordproductivty.med_timing_tracker.notifications

import android.app.AlarmManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build

object ExactAlarmScheduler {
    const val EXTRA_DOSE_LOG_ID = "dose_log_id"
    const val EXTRA_TITLE = "title"
    const val EXTRA_TEXT = "text"

    fun canScheduleExact(context: Context): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S) return true
        val alarmManager = context.getSystemService(AlarmManager::class.java)
        return alarmManager.canScheduleExactAlarms()
    }

    fun schedule(context: Context, doseLogId: Int, triggerAtMillis: Long, title: String, text: String) {
        cancel(context, doseLogId)
        if (!canScheduleExact(context)) return
        val alarmManager = context.getSystemService(AlarmManager::class.java)
        alarmManager.setExactAndAllowWhileIdle(
            AlarmManager.RTC_WAKEUP,
            triggerAtMillis,
            pendingIntent(context, doseLogId, title, text),
        )
    }

    fun cancel(context: Context, doseLogId: Int) {
        val alarmManager = context.getSystemService(AlarmManager::class.java)
        alarmManager.cancel(pendingIntent(context, doseLogId, "", ""))
        NotificationHelper.cancel(context, doseLogId)
    }

    private fun pendingIntent(context: Context, doseLogId: Int, title: String, text: String): PendingIntent {
        val intent = Intent(context, ReminderAlarmReceiver::class.java).apply {
            putExtra(EXTRA_DOSE_LOG_ID, doseLogId)
            putExtra(EXTRA_TITLE, title)
            putExtra(EXTRA_TEXT, text)
        }
        return PendingIntent.getBroadcast(
            context,
            doseLogId,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE,
        )
    }
}
